import os
providers={'groq':['GROQ_API_KEY'],'mistral':['MISTRAL_API_KEY'],'nvidia':['NVIDIA_API_KEY','NGC_API_KEY']}
for p,bases in providers.items():
    names=set()
    for base in bases:
        if os.getenv(base): names.add(base)
        for k,v in os.environ.items():
            if k.startswith(base+'_') and v.strip(): names.add(k)
    listname=p.upper()+'_API_KEYS'
    if os.getenv(listname):
        n=sum(1 for x in os.environ[listname].replace(';',',').replace('\n',',').split(',') if x.strip())
    else: n=0
    print(p,'named_envs',len(names),'list_entries',n)
